Worked example:

```javascript
function removeNote(notes,id) {
  return notes.filter(note=>note.id !== id);
}
console.log(removeNote([{"id":1},{"id":2},{"id":3}], 2));
```
The returned value is [{"id":1},{"id":3}].

after:
```javascript
function removeNote(notes,id) {
  return notes.filter(note=>note.id !== id);
}
console.log(removeNote([{"id":1},{"id":2},{"id":3}], 2));
```
The result contains IDs 1 and 3. ID 2 is left out, and the remaining notes keep their order.
